@Entity()
// highlight-next-line
class MyBaseEntity<Entity extends object, Optional extends keyof Entity = never> {

  // highlight-next-line
  [OptionalProps]?: 'foo' | 'bar' | Optional;

  @PrimaryKey()
  id!: number;

  @Property({ default: 1 })
  foo: number = 1;

  @Property({ default: 2 })
  bar: number = 2;

}

@Entity()
// highlight-next-line
